fn write_default_themes() {
    let config_dir = PathBuf::from("/home/agent/.config/tui-journal");
    if !config_dir.exists() {
        fs::create_dir_all(&config_dir).expect("Failed to create config directory");
    }
    let themes_file = config_dir.join("themes.toml");
    let content = get_default_themes_content();
    fs::write(&themes_file, content).expect("Failed to write themes file");
    println!("Default themes have been written to {}", themes_file.display());
}
```

